import java.util.Scanner;// -------------------------------------------------------------------------/** * runs SARS cov 3 health check and builds a descion tree from the file * *  * @author pragati ANandarajan * @version Oct 6, 2026 */public class Driver{    // ----------------------------------------------------------    /**     * starts the applicaiton     *      * @param args     */    public static void main(String[] args)    {        if (args.length < 1)        {            System.out.println("Please provide the file name");            System.exit(0);        }        SARSCoV3HealthBuilder build = new SARSCoV3HealthBuilder(args[0]);        String response;        do        {            build.decide();            System.out.print("Try again? ");            response = getUserResponse();        }        while (response.toLowerCase().equals("yes"));        System.out.println("Have a nice day!");    }    // ----------------------------------------------------------    /**     * Reads one line of input from the user.     *     * @return the text the user typed     */    public static String getUserResponse()    {        Scanner keyboard = new Scanner(System.in);        String response = keyboard.nextLine();        return response;    }    /**     * Reads one line of input from the user and checks whether it is "yes",     * ignoring upper and lower case.     *     * @return true if the user typed yes, false for anything else     */    public static boolean isUserResponseYes()    {        String answer = getUserResponse();        if (answer.toLowerCase().equals("yes"))            return true;        return false;    }}